import{_ as a,o as n,c as i,a2 as e}from"./chunks/framework.DYYBR_aZ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"tools/git的使用.md","filePath":"tools/git的使用.md"}'),t={name:"tools/git的使用.md"};function p(l,s,o,r,c,h){return n(),i("div",null,[...s[0]||(s[0]=[e(`<p>我们需要知道文件夹，暂存区，本地仓库，远程仓库；</p><h3 id="拉取仓库" tabindex="-1">拉取仓库 <a class="header-anchor" href="#拉取仓库" aria-label="Permalink to &quot;拉取仓库&quot;">​</a></h3><p>输入 git clone <a href="https://gitee.com/WTY2002/chat-room.git%E5%B0%B1%E5%8F%AF%E4%BB%A5%E5%B0%86%E8%BF%9C%E7%A8%8B%E4%BB%93%E5%BA%93%E6%8B%89%E5%88%B0%E6%88%91%E4%BB%AC%E7%9A%84%E6%9C%AC%E5%9C%B0" target="_blank" rel="noreferrer">https://gitee.com/WTY2002/chat-room.git就可以将远程仓库拉到我们的本地</a></p><blockquote><p><code>git clone</code> 会自动创建一个名为 <code>origin</code> 的远程别名，并默认切换到远程仓库的默认分支（通常是 <code>master</code> 或 <code>main</code>）。</p></blockquote><h3 id="本地仓库关联远程仓库" tabindex="-1">本地仓库关联远程仓库： <a class="header-anchor" href="#本地仓库关联远程仓库" aria-label="Permalink to &quot;本地仓库关联远程仓库：&quot;">​</a></h3><div class="language-git vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">git</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add origin https://gitee.com/你的用户名/仓库名.git</span></span></code></pre></div><p>具体来说，<code>git remote add origin </code> 做的事情是：把远程仓库的地址写入本地仓库的配置文件 <code>.git/config</code> 里，给它起个别名叫 <code>origin</code>。你可以打开 <code>.git/config</code> 看看，大概长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[remote &quot;origin&quot;]</span></span>
<span class="line"><span>    url = https://gitee.com/你的用户名/仓库名.git</span></span>
<span class="line"><span>    fetch = +refs/heads/*:refs/remotes/origin/*</span></span></code></pre></div><p>所以它既不是暂存区（staging area / index），也不是文件夹本身：</p><ul><li><strong>暂存区</strong>是 <code>.git/index</code>，只管&quot;哪些文件改动准备提交&quot;，跟远程地址没有任何关系。</li><li><strong>文件夹</strong>（工作区）是你看到的文件和目录，Git 远程配置也不存在那里。</li><li><strong>本地仓库</strong>（<code>.git/</code>）才是所有元数据、历史、配置、远程关联的存放地。</li></ul><p>简单记：<code>git remote add</code> = 给本地仓库配一个&quot;远程搭档&quot;的地址和名字。</p><h3 id="删除已关联的远程仓库" tabindex="-1">删除已关联的远程仓库 <a class="header-anchor" href="#删除已关联的远程仓库" aria-label="Permalink to &quot;删除已关联的远程仓库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote remove origin</span></span></code></pre></div><p>其实这就是解绑，他只是把叫 <code>origin</code> 的远程地址记录，不会影响远程仓库上的任何东西，也不会动你的代码和历史。就像你把通讯录里某个联系人的电话删了，对方不会有任何感知。之后想用还可以重新 <code>git remote add</code> 加回来。</p><h3 id="常见指令" tabindex="-1">常见指令 <a class="header-anchor" href="#常见指令" aria-label="Permalink to &quot;常见指令&quot;">​</a></h3><h4 id="查看类" tabindex="-1">查看类 <a class="header-anchor" href="#查看类" aria-label="Permalink to &quot;查看类&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看已关联的远程仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看文件状态（红=未暂存，绿=已暂存）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确认当前分支（本地仓库）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#如果想看远程分支，可用：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">例如可能会看到：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin/master</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin/arch-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin/arch-server-amaidou</span></span></code></pre></div><h4 id="操作类" tabindex="-1">操作类 <a class="header-anchor" href="#操作类" aria-label="Permalink to &quot;操作类&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span># 把当前目录所有变更加入暂存区（. 代表当前目录）</span></span>
<span class="line"><span>git add .</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># 提交到本地仓库（-m 后是提交信息，必须写清楚做了什么）</span></span>
<span class="line"><span>git commit -m &quot;新增/修改：xxx功能&quot;</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># 拉取远程仓库最新代码（避免冲突）</span></span>
<span class="line"><span>git pull origin master</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># 推送到远程仓库（第一次推送需要 -u 关联分支）</span></span>
<span class="line"><span>git push -u origin master</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># 后续推送（已关联分支后）</span></span>
<span class="line"><span>git push</span></span></code></pre></div><h3 id="一个小趣文" tabindex="-1">一个小趣文 <a class="header-anchor" href="#一个小趣文" aria-label="Permalink to &quot;一个小趣文&quot;">​</a></h3><p>![git push 的注意事项](../imags/git push的注意事项.png)</p><p>正常人都会先 <code>git pull --rebase</code> 再 push，直接 <code>-f</code> 强推确实让人血压飙升。</p><h3 id="关于拉取pull" tabindex="-1">关于拉取pull <a class="header-anchor" href="#关于拉取pull" aria-label="Permalink to &quot;关于拉取pull&quot;">​</a></h3><p><strong><code>git pull</code> = 把远程仓库的最新代码拉到本地，并合并到你当前的分支。</strong></p><p>它其实是两个操作的合体：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git pull = git fetch + git merge</span></span></code></pre></div><ul><li><strong>git fetch</strong>：从远程仓库下载最新数据到本地（只下载，不动你的代码）</li><li><strong>git merge</strong>：把下载来的远程分支合并到你当前工作分支</li></ul><p>什么时候需要 git pull</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>开始一天的工作前</td><td>拉取团队最新代码，避免在过时的基础上开发</td></tr><tr><td>push 之前</td><td>远程有你不知道的新提交时，必须先 pull 再 push</td></tr><tr><td>同事更新了共享分支</td><td>保持同步</td></tr></tbody></table><h3 id="关于推送push" tabindex="-1">关于推送push <a class="header-anchor" href="#关于推送push" aria-label="Permalink to &quot;关于推送push&quot;">​</a></h3><p>什么时候 push 会失败</p><p>最常见的报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>! [rejected]        main -&gt; main (fetch first)</span></span>
<span class="line"><span>error: failed to push some refs to &#39;origin&#39;</span></span>
<span class="line"><span>hint: Updates were rejected because the remote contains work that you do</span></span>
<span class="line"><span>hint: not have locally.</span></span></code></pre></div><p>这正是上面同事遇到的场景。正确的处理顺序是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. 先拉下来合并</span></span>
<span class="line"><span>git pull origin main</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 有冲突就解决冲突，然后 commit</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 再 push</span></span>
<span class="line"><span>git push origin main</span></span></code></pre></div><p>相关链接，在我个人博客里：</p><p>git 常见命令：<a href="https://blog.csdn.net/weixin_54946088/article/details/157059951" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_54946088/article/details/157059951</a></p><p>git的使用：<a href="https://blog.csdn.net/weixin_54946088/article/details/153915362" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_54946088/article/details/153915362</a></p><p>git的介绍：<a href="https://blog.csdn.net/weixin_54946088/article/details/138465313" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_54946088/article/details/138465313</a></p>`,39)])])}const u=a(t,[["render",p]]);export{g as __pageData,u as default};
